// Package icons holds the tray icons, one per VM status.
// The PNGs are placeholders generated by scripts/phase0/gen-icons.py.
package icons

import (
	_ "embed"

	"github.com/tricknotes/merry-desktop/internal/vm"
)

var (
	//go:embed tray-stopped.png
	stopped []byte
	//go:embed tray-starting.png
	starting []byte
	//go:embed tray-running.png
	running []byte
	//go:embed tray-error.png
	failed []byte
)

// Tray returns the PNG for a status.
func Tray(s vm.Status) []byte {
	switch s {
	case vm.StatusStarting:
		return starting
	case vm.StatusRunning:
		return running
	case vm.StatusError:
		return failed
	default:
		return stopped
	}
}
